87:         Playwright playwright = null;
88:         Browser browser = null;
89:         Page page = null;
91:         try {
93:             log.debug("Playwright 인스턴스 생성");
94:             playwright = Playwright.create();
97:             log.debug("Chromium 브라우저 시작 (headless 모드)");
98:             browser = playwright.chromium().launch(
99:                     new BrowserType.LaunchOptions()
100:                             .setHeadless(true)
101:                             .setSlowMo(100)
102:             );
104:             page = browser.newPage();
107:             String url = TRACKING_URL_PREFIX + trackingNumber;
108:             log.debug("배송 조회 페이지로 이동: {}", url);
109:             page.navigate(url);
112:             log.debug("배송 상태 테이블 로드 대기 (최대 {}ms)", SELECTOR_TIMEOUT_MS);
113:             page.setDefaultTimeout(SELECTOR_TIMEOUT_MS);
114:             page.waitForSelector(STATUS_SELECTOR);
117:             log.debug("페이지 HTML 로드");
118:             String renderedHtml = page.content();
121:             log.debug("HTML 파싱 시작");
122:             String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
123:             log.info("배송 상태 파싱 완료: 운송장={}, 상태={}", trackingNumber, statusText);
125:             return statusText;
127:         } catch (Exception e) {
128:             log.error("배송 상태 조회 실패: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
130:             if (e instanceof AddressException) {
131:                 throw e;
132:             }
134:             throw new AddressException(
135:                     AddressErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
136:                     "CJ대한통운 배송 조회 중 오류 발생: " + e.getMessage(),
137:                     e
138:             );
139:         } finally {
141:             log.debug("리소스 해제 시작");
143:             try {
144:                 if (page != null) {
145:                     page.close();
146:                 }
148:                 if (browser != null) {
149:                     browser.close();
150:                 }
152:                 if (playwright != null) {
153:                     playwright.close();
154:                 }
156:                 log.debug("리소스 해제 완료");
157:             } catch (Exception e) {
158:                 log.warn("리소스 해제 중 오류 발생: {}", e.getMessage());
159:             }
160:         }
161:     }
171:     private String parseStatusFromHtml(String html, String trackingNumber) {
