205:             if (e instanceof AddressException) {
206:                 throw (AddressException) e;
207:             }
209:             log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
210:             throw new AddressException(
211:                     AddressErrorCode.TRACKING_HTML_PARSE_ERROR,
212:                     "배송 상태 정보 파싱 실패: " + e.getMessage(),
213:                     e
214:             );
215:         }
216:     }
217: }
